const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SalesSim</title><meta name="description" content="AI-powered, evidence-backed sales practice"><style>
*{box-sizing:border-box}body{margin:0;background:#f6f8fb;color:#172033;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.side{background:#0f172a;color:white;padding:24px 18px}.brand{font-size:22px;font-weight:750}.org{font-size:12px;color:#94a3b8;margin:5px 0 28px}.nav a{display:block;color:#cbd5e1;text-decoration:none;padding:10px 12px;border-radius:9px;font-size:14px;margin:2px 0}.nav a:hover,.nav a.on{background:#1e293b;color:white}.main{padding:42px;max-width:1440px;width:100%}.eyebrow{font-size:12px;font-weight:800;color:#2563eb;letter-spacing:.05em}.title{font-size:34px;letter-spacing:-.03em;margin:8px 0}.muted{color:#64748b}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.card{background:white;border:1px solid #e2e8f0;border-radius:16px;padding:20px;box-shadow:0 1px 3px #0f172a0a}.metric strong{display:block;font-size:26px;margin-top:7px}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:20px}.badge{display:inline-block;border:1px solid #bfdbfe;border-radius:999px;background:#eff6ff;color:#1d4ed8;padding:5px 9px;font-size:11px;font-weight:800}.btn{border:0;border-radius:10px;background:#2563eb;color:white;font-weight:750;padding:11px 15px;cursor:pointer;text-decoration:none;display:inline-block}.btn.alt{border:1px solid #cbd5e1;background:white;color:#172033}.actions{display:flex;gap:10px;margin-top:20px}.hidden{display:none!important}.room{display:grid;grid-template-columns:1fr 290px;gap:20px}.chat{min-height:680px;display:flex;flex-direction:column}.messages{flex:1;padding:20px 0;overflow:auto}.bubble{max-width:76%;padding:12px 14px;border-radius:17px;background:#f1f5f9;margin:10px 0;line-height:1.5;font-size:14px}.bubble.me{margin-left:auto;background:#2563eb;color:white}.who{font-size:10px;font-weight:800;text-transform:uppercase;opacity:.65;margin-bottom:4px}.composer{display:flex;gap:8px}.composer textarea{flex:1;border:1px solid #cbd5e1;border-radius:10px;padding:12px;resize:none}.rubric{display:grid;gap:10px}.criterion{display:grid;grid-template-columns:1fr auto;gap:14px}.score{font-size:23px;font-weight:800}.evidence{background:#f8fafc;border-radius:10px;padding:12px;margin-top:12px;font-size:13px}.list{padding-left:20px;color:#475569;line-height:1.8}.studio{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.row{display:flex;justify-content:space-between;border-bottom:1px solid #f1f5f9;padding:9px 0;font-size:13px}@media(max-width:900px){.shell{display:block}.side{padding:16px}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.main{padding:24px}.metrics,.studio{grid-template-columns:1fr 1fr}.grid,.room{grid-template-columns:1fr}}@media(max-width:560px){.metrics,.studio{grid-template-columns:1fr}.title{font-size:29px}.main{padding:18px}.side{position:static}.bubble{max-width:90%}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">SalesSim</div><div class="org">Northstar demo · Manager</div><nav class="nav"><a href="#home" data-go="home">Home</a><a href="#practice" data-go="practice">Practice</a><a href="#studio" data-go="studio">Scenarios</a><a href="#results" data-go="results">Results</a><a href="#team" data-go="team">Team</a></nav></aside><main class="main">
<section id="home"><div class="eyebrow">MANAGER WORKSPACE</div><h1 class="title">Good morning, Alex</h1><p class="muted">Your team's discovery practice at a glance.</p><div class="metrics"><div class="card metric"><span class="muted">Completed</span><strong>24</strong></div><div class="card metric"><span class="muted">Average score</span><strong>72</strong></div><div class="card metric"><span class="muted">Active reps</span><strong>8</strong></div><div class="card metric"><span class="muted">Weakest skill</span><strong style="font-size:18px">Business impact</strong></div></div><div class="grid"><div class="card"><span class="badge">Published · Demo data</span><h2>Northstar forecasting discovery</h2><p class="muted">Practice qualifying a deeper discovery meeting with Jordan Lee, a skeptical VP of Sales Operations.</p><div class="actions"><button class="btn" data-go="practice">Start practice</button><button class="btn alt" data-go="studio">Review scenario</button></div></div><div class="card"><h3>Recommended team drill</h3><strong>From symptoms to business impact</strong><p class="muted">Reps identify spreadsheet friction but stop before quantifying leadership impact.</p></div></div></section>
<section id="practice" class="hidden"><div class="room"><div class="card chat"><div><div class="eyebrow">LIVE TEXT PRACTICE · 09:42</div><h2>Jordan Lee <span class="muted" style="font-weight:400">· VP of Sales Operations</span></h2></div><div id="messages" class="messages"><div class="bubble"><div class="who">Jordan</div>Hi, I have about ten minutes. What did you want to cover?</div></div><div class="composer"><textarea id="message" rows="2" aria-label="Reply to Jordan" placeholder="Reply to Jordan…"></textarea><button class="btn" id="send">Send</button></div></div><aside><div class="card"><span class="badge">Medium</span><h3>Your objective</h3><p class="muted">Determine whether a deeper discovery meeting is justified.</p><h4>Known facts</h4><ul class="list"><li>Distributed sales team</li><li>Meeting followed an outbound email</li><li>You have 10 minutes</li></ul></div><button class="btn alt" style="width:100%;margin-top:14px" data-go="results">End call</button></aside></div></section>
<section id="studio" class="hidden"><div class="eyebrow">SCENARIO STUDIO · VERSION 1</div><h1 class="title">Northstar forecasting discovery</h1><p class="muted">Structured sales concepts are compiled into private internal prompts.</p><div class="studio" style="margin-top:26px"><div class="card"><span class="badge">A · Rep sees</span><h2>Pre-call brief</h2><p><b>Account</b><br><span class="muted">Northstar Systems</span></p><p><b>Buyer</b><br><span class="muted">Jordan Lee · VP Sales Operations</span></p><p><b>Objective</b><br><span class="muted">Qualify a deeper discovery meeting.</span></p></div><div class="card"><span class="badge">B · Buyer knows</span><h2>Private scenario</h2><p class="muted">Regional forecasts arrive late, spreadsheet formats are inconsistent, and leadership does not trust the weekly forecast.</p><div class="evidence"><b>Hidden pain · Severity 4</b><br>Low forecast trust and manual reconciliation.</div></div><div class="card"><span class="badge">C · Scorecard</span><h2>Weighted rubric</h2><div id="weights"></div></div></div><div class="actions"><button class="btn alt">Save draft</button><button class="btn">Publish version</button></div></section>
<section id="results" class="hidden"><div class="eyebrow">EVIDENCE-BACKED RESULTS</div><div style="display:flex;align-items:end;gap:12px"><div style="font-size:64px;font-weight:800">72</div><div class="muted" style="padding-bottom:12px">/ 100 · neutral</div></div><h1>Northstar forecasting discovery</h1><div class="grid"><div id="rubric" class="rubric"></div><aside><div class="card"><h3>Strengths</h3><ul class="list"><li>Established a professional conversation</li><li>Asked about the current process</li></ul></div><div class="card" style="margin-top:14px"><h3>Priority improvements</h3><ul class="list"><li>Quantify business impact</li><li>Secure a concrete next step</li></ul></div><div class="card" style="margin-top:14px"><span class="badge">Next drill</span><h3>Business-impact discovery</h3><p class="muted">Practice moving from symptoms to measurable consequences.</p></div><button class="btn" style="margin-top:14px" data-go="practice">Retry scenario</button></aside></div></section>
<section id="team" class="hidden"><div class="eyebrow">TEAM PERFORMANCE</div><h1 class="title">Competency trends</h1><div class="card"><h2>Recent sessions</h2><div class="row"><b>Maya Chen</b><span>Discovery · 81</span></div><div class="row"><b>Sam Rivera</b><span>Discovery · 74</span></div><div class="row"><b>Alex Morgan</b><span>Discovery · 68</span></div></div></section>
</main></div><script>
const sections=[...document.querySelectorAll('main>section')];function go(id){sections.forEach(s=>s.classList.toggle('hidden',s.id!==id));document.querySelectorAll('[data-go]').forEach(a=>a.classList.toggle('on',a.dataset.go===id));location.hash=id;scrollTo(0,0)}document.querySelectorAll('[data-go]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();go(x.dataset.go)}));go(location.hash.slice(1)||'home');
const criteria=[['Opening and agenda',10],['Question quality',15],['Pain discovery',20],['Business-impact discovery',20],['Active listening',15],['Relevant positioning',10],['Next-step control',10]];document.querySelector('#weights').innerHTML=criteria.map(x=>'<div class="row"><span>'+x[0]+'</span><b>'+x[1]+'%</b></div>').join('');document.querySelector('#rubric').innerHTML=criteria.map((x,i)=>'<article class="card criterion"><div><h3 style="margin-top:0">'+x[0]+'</h3><p class="muted">Observable seller behavior measured against anchored criteria.</p><div class="evidence"><b>Transcript evidence · turn s'+(i%2+1)+'</b><br>“'+(i%2?'What impact does that have on the weekly leadership review?':'Could you walk me through how your forecast is assembled today?')+'”</div><p class="muted">Evidence '+(i<2?'effectively':'partially')+' supports this criterion. Ask one more specific follow-up.</p></div><div class="score">'+(i<2?3:2)+'/4</div></article>').join('');
const box=document.querySelector('#message'),msgs=document.querySelector('#messages');function send(){const text=box.value.trim();if(!text)return;msgs.insertAdjacentHTML('beforeend','<div class="bubble me"><div class="who">You</div>'+text.replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))+'</div>');box.value='';setTimeout(()=>{const q=text.toLowerCase();let r='What specifically would you like to understand about our process?';if(/how.*forecast|assembled|current process/.test(q))r='Regional leaders send spreadsheets in different formats, and my team consolidates them before the weekly review.';else if(/impact|leadership|consequence/.test(q))r='The reports arrive late enough that leadership questions the weekly forecast. My team spends too much time reconciling the numbers.';else if(/platform|solution|technology|demo/.test(q))r='We already have reporting in our CRM. I don’t want another system that creates more administrative work.';else if(/rubric|score|prompt|hidden/.test(q))r='I’m not sure what you mean. Are we going to discuss our forecasting process?';msgs.insertAdjacentHTML('beforeend','<div class="bubble"><div class="who">Jordan</div>'+r+'</div>');msgs.scrollTop=msgs.scrollHeight},450)}document.querySelector('#send').onclick=send;box.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});
</script></body></html>`;
export default { async fetch(request) { const url=new URL(request.url); if(url.pathname==='/health') return new Response('ok'); return new Response(page,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=60'}}); } };
